/* ===== tracks theke playlist toiri (eta bodlate hobe na) ===== */
const LISTS={durga:"Durga Puja",mahalaya:"Mahalaya"};
const COLORS=["#c2185b","#e65100","#6a1b9a","#00695c","#8d3b00","#455a64","#b71c1c","#1565c0","#827717","#4e342e"];
function toSec(m){return String(m).split(':').reduce((a,v)=>a*60+(+v||0),0)}
const SONGS=tracks.map((x,i)=>({t:x.name,a:x.artist,d:toSec(x.dur),src:x.src||"",thumb:x.thumb||"",cat:x.cat,list:x.list,c:COLORS[i%COLORS.length]}));
const PLAYLISTS={};
Object.keys(LISTS).forEach(k=>{const L=SONGS.filter(s=>s.list===k);if(L.length)PLAYLISTS[LISTS[k]]=L});
[...new Set(SONGS.map(s=>s.cat))].forEach(c=>{if(!PLAYLISTS[c])PLAYLISTS[c]=SONGS.filter(s=>s.cat===c)});
PLAYLISTS["All Songs"]=SONGS;

